module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (decode, getString, getInt, getArray)
import std/string (split)
import std/list (length)

type Config = { appName: string, version: string, port: int, featureCount: int }

pure func validatePort(port: int) -> bool = port >= 1024 && port <= 65535

pure func validateVersion(v: string) -> bool = length(split(v, ".")) == 3

func loadConfig(path: string) -> Result[Config, string] ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Err(e) => Err("Parse error: ${e}"),
    Ok(obj) => match (getString(obj, "app_name"), getString(obj, "version"), getInt(obj, "port"), getArray(obj, "features")) {
      (Some(name), Some(ver), Some(port), Some(features)) =>
        if not validatePort(port) then Err("Invalid port")
        else if not validateVersion(ver) then Err("Invalid version")
        else if length(features) == 0 then Err("Features list is empty")
        else Ok({ appName: name, version: ver, port: port, featureCount: length(features) }),
      _ => Err("Missing or invalid field")
    }
  }
}

export func main() -> () ! {IO, FS} {
  writeFile("app_config.json", "{\"app_name\": \"MyApp\", \"version\": \"1.0.0\", \"port\": 8080, \"features\": [\"logging\", \"auth\", \"api\"]}");
  match loadConfig("app_config.json") {
    Ok(c) => println("Loaded ${c.appName} v${c.version} on port ${show(c.port)} with ${show(c.featureCount)} features"),
    Err(e) => println("Error: ${e}")
  }
}

